const HEBREW = /[֐-׿]/;

/** Гейт для тестов, отправляющих реальное SMS. */
export function requireSms(ctx: Mocha.Context) {
  if (!driver.isAndroid) skipWith(ctx, 'OTP-пакет 03.11 принят на Android (Pixel 6); iPhone не проверялся');
  if (process.env.QA_SMS !== '1') skipWith(ctx, 'тест отправляет платное SMS (Pulseem) — запуск с QA_SMS=1');
  if (!OTP_PHONE) skipWith(ctx, 'нет QA_OTP_PHONE — реальный номер, SMS на котором читает человек');
}
export function requireManualOtp(ctx: Mocha.Context) {
  if (process.env.QA_OTP_MANUAL !== '1') skipWith(ctx, '@manual-otp: код из SMS вводит человек — запуск с QA_OTP_MANUAL=1 и человеком у телефона');
}

/** Последние 9 цифр (05X… и +972… сравниваются одинаково). */
export const digits9 = (v: string) => v.replace(/\D/g, '').slice(-9);

/** Клетка кода n (1..6). */
export const digitCell = (n: number) => byLabel(`ספרה ${n} מתוך שש`);

export async function hideKeyboardIfShown() {
  if (await driver.isKeyboardShown().catch(() => false)) await driver.hideKeyboard().catch(() => {});
}

/** Выйти из аккаунта (если вошли) и открыть экран номера. */
export async function toPhoneScreen() {
  if (await isLoggedIn()) await logout();
  const start = await byText(START);
  if (await shown(start)) await start.click();
  await expect(byText(PHONE_TITLE)).toBeDisplayed({ wait: 20000 });
}

/** Поле «מספר נייד» (EditText на экране номера). */
export async function phoneField(): Promise<WebdriverIO.Element> {
  const byDesc = (await byLabel('מספר נייד')) as unknown as WebdriverIO.Element;
  if (await byDesc.isExisting().catch(() => false)) return byDesc;
  return (await (driver.isAndroid
    ? $('android=new UiSelector().className("android.widget.EditText")')
    : $('-ios class chain:**/XCUIElementTypeTextField'))) as unknown as WebdriverIO.Element;
}

/** Ввести номер и нажать «שילחו קוד אימות» (без ожидания результата). */
export async function submitPhone(phone: string) {
  const f = await phoneField();
  await f.waitForDisplayed({ timeout: 15000 });
  await f.clearValue();                       // поле заранее заполнено мокап-номером — это норма
  await f.setValue(phone);
  expect(digits9(await fieldValue(f))).toBe(digits9(phone));
  await hideKeyboardIfShown();
  const send = await byText(SEND_CODE);
  await send.waitForDisplayed({ timeout: 10000 });
  await send.click();
}

/** Экран «קוד אימות» открыт (6 клеток). */
export async function waitCodeScreen(timeout = 30000) {
  await expect(byText(CODE_TITLE)).toBeDisplayed({ wait: timeout });
  await expect(digitCell(1)).toBeExisting({ wait: 10000 });
}

/** Ввести код по клеткам «ספרה N מתוך שש» (одной строкой в первую клетку цифры теряются — урок 4-значного кода). */
export async function typeCode(code: string) {
  if (code.length !== 6) throw new Error(`код должен быть 6 цифр, получено ${code.length}`);
  for (let i = 0; i < 6; i++) {
    const cell = await digitCell(i + 1);
    await cell.click();
    await cell.setValue(code[i]);
    await driver.waitUntil(async () => (await fieldValue(cell as unknown as WebdriverIO.Element)).includes(code[i]),
      { timeout: 5000, interval: 200, timeoutMsg: `клетка ${i + 1} не приняла цифру` });
  }
}

/** Значения клеток (для «цифры не стёрты после ошибки»). */
export async function cellValues(): Promise<string> {
  let s = '';
  for (let n = 1; n <= 6; n++) s += (await fieldValue((await digitCell(n)) as unknown as WebdriverIO.Element)).replace(/\D/g, '');
  return s;
}

/** Нажать «שלח» на экране кода: клавиатуру спрятать ДО нажатия. Если код отправился сам — кнопки может не быть. */
export async function tapSubmit() {
  await hideKeyboardIfShown();
  const b = await byText(SUBMIT);
  if (await b.isDisplayed().catch(() => false)) await b.click();
}

/** Текст-сообщение на экране, начинающийся с префикса (или null). */
export async function messageStartingWith(prefix: string): Promise<string | null> {
  const el = await byTextContains(prefix);
  if (!(await el.isExisting().catch(() => false))) return null;
  return (await el.getText()) || String((await el.getAttribute('content-desc').catch(() => '')) ?? '');
}

/** Сообщение на иврите, начинающееся с префикса, появилось. */
export async function expectHebrewMessage(prefix: string, timeout = 30000) {
  let text: string | null = null;
  await driver.waitUntil(async () => !!(text = await messageStartingWith(prefix)),
    { timeout, interval: 500, timeoutMsg: `нет сообщения «${prefix}…»` });
  expect(HEBREW.test(text!)).toBe(true);
  return text!;
}

/** Строки «מצב בדיקה» на экране нет. */
export async function expectNoTestMode() {
  await expect(byTextContains(TEST_MODE)).not.toBeExisting();
}

/** Ждать, пока человек сделает шаг, — до появления любого из ожидаемых текстов. Возвращает, какой появился. */
export async function waitHumanFor(what: string, texts: string[], timeout = MANUAL_WAIT): Promise<string> {
  console.log(`[app-e2e 03.11] @manual-otp: ${what}. Тест ждёт до ${Math.round(timeout / 60000)} мин…`);
  let hit = '';
  await driver.waitUntil(async () => {
    for (const t of texts) {
      if (t === '__HOME__' ? await isLoggedIn() : await (await byTextContains(t)).isExisting().catch(() => false)) { hit = t; return true; }
    }
    return false;
  }, { timeout, interval: 1500, timeoutMsg: `не дождались: ${texts.join(' | ')}` });
  return hit;
}

// ───────────────────────── сеть (офлайн) ─────────────────────────

/** Выключить/включить сеть: Android — `mobile: setConnectivity` (Wi‑Fi + данные). Не вышло или QA_OFFLINE_MANUAL=1 — человек (авиарежим). */
export async function setOnline(on: boolean) {
  const manual = process.env.QA_OFFLINE_MANUAL === '1' || !driver.isAndroid;
  if (!manual) {
    try {
      await driver.execute('mobile: setConnectivity', { wifi: on, data: on });
      return;
    } catch (e) {
      console.log(`[app-e2e 03.11] setConnectivity не сработал (${(e as Error).message}) — переключите сеть вручную`);
    }
  }
  console.log(`[app-e2e 03.11] ${on ? 'ВКЛЮЧИТЕ' : 'ВЫКЛЮЧИТЕ'} сеть (авиарежим ${on ? 'выкл' : 'вкл'}) и ничего не нажимайте в приложении…`);
  await driver.waitUntil(async () => {
    const st = await driver.execute('mobile: getConnectivity', {}).catch(() => null) as { wifi?: boolean; data?: boolean; airplaneMode?: boolean } | null;
    if (!st) return true;   // статус не читается — полагаемся на человека
    return on ? !!(st.wifi || st.data) && !st.airplaneMode : !st.wifi && !st.data;
  }, { timeout: MANUAL_WAIT, interval: 2000, timeoutMsg: `сеть не стала ${on ? 'включённой' : 'выключенной'}` });
}

