// Путь (факт 03.11, iPhone 17): «מעבר לפרטים שלי» → «פרופיל אישי» → «עריכת השם» → поле «שם מלא» → «שמירה»
// («שם מלא: השינוי נשמר.») → «חזרה» → «בית». Меняет «שם מלא» вошедшего аккаунта — вызывающий тест обязан вернуть имя (finally).

/** Длинное имя, на котором мерили 03.11 (q-25 — 4 строки приветствия, q-26 — шапка с многоточием). */
export const NAME_LONG = 'Tatiana Dombek Alexandrovna Longname';
export const FALLBACK_NAME = process.env.QA_GREETING_RESTORE_NAME || 'QA reg 0311';

export async function openNameEditor() {
  await toHome();
  await tapLabel('מעבר לפרטים שלי');
  await (await byText('פרופיל אישי')).waitForDisplayed({ timeout: 20000 });
  await tapLabel('עריכת השם');
  const f = await byLabel('שם מלא');
  await f.waitForDisplayed({ timeout: 15000 });
  return f;
}

export async function backToHome() {
  const back = await byText('חזרה');
  if (await back.isDisplayed().catch(() => false)) await back.click();
  await toHome();
}

/** Текущее «שם מלא» из поля (пусто → FALLBACK_NAME). */
export async function readProfileName(): Promise<string> {
  const f = await openNameEditor();
  const v = (await f.getText()).trim() || FALLBACK_NAME;
  await backToHome();
  return v;
}

export async function setProfileName(name: string) {
  const f = await openNameEditor();
  await f.clearValue();
  await f.setValue(name);
  await (await byText('שמירה')).click();
  await expectTextContains('שם מלא: השינוי נשמר.');
  await backToHome();
}

type ElGetter = () => ReturnType<typeof byText> | Promise<WebdriverIO.Element | undefined>;

/** Рамка элемента, переставшая меняться (после смены имени шапка перестраивается). */
export async function stableRect(get: ElGetter, what: string, timeout = 20000): Promise<Rect> {
  let prev = '';
  let last: Rect | undefined;
  await driver.waitUntil(async () => {
    const el = (await get()) as WebdriverIO.Element | undefined;
    if (!el || !(await el.isDisplayed().catch(() => false))) return false;
    last = await rectOf(el);
    const key = JSON.stringify(last);
    const same = key === prev;
    prev = key;
    return same;
  }, { timeout, interval: 500, timeoutMsg: `рамка не стабилизировалась: ${what}` });
  return last!;
}
